// 通用 AOE 组件：复用 CriticalEngagement 的重复包/墓碑去重逻辑，按战斗分组过滤。
[SkipLocalsInit]
class CrucibleCastAOEs(BossModule module, Battle battle) : ReplayValidatedCastAOEs(module)
{
    private readonly Battle _battle = battle;

    protected override AOEConfig? ConfigFor(uint actionID)
    {
        if ((_battle == Battle.B04 && (CrucibleGroundUpliftAOEs.IsUplift(actionID) || actionID == 46908))
            || !CrucibleSpells.Table.TryGetValue(actionID, out var spell))
        {
            return null;
        }
        // 只有本组敌人的技能才绘制
        var battles = CrucibleSpellBattles.BattlesFor(actionID);
        // First-board NPC cast packets carry the actual AOE origin, including relocated helpers.
        return battles.Contains(_battle) ? new AOEConfig(spell.Shape, _battle <= Battle.B07 || spell.LocationTargeted) : null;
    }
}

